/**
 * cards/art.js — where the web card's art lives. GENERATED by
 * scripts/card-art-webp.py from src/assets/cards/art/*.png; do not edit by hand.
 * WebP for the screen (the PNGs are the print masters), with a content hash so
 * the files can be cached for a year.
 */
const URLS = Object.freeze({
  "alumni": "/assets/cards/art/alumni.webp?v=5f1b1f30af",
  "forge": "/assets/cards/art/forge.webp?v=a8e891079b",
  "kaayko": "/assets/cards/art/kaayko.webp?v=63667b2ae6",
  "kortex": "/assets/cards/art/kortex.webp?v=69de4faf4c",
  "paddlingout": "/assets/cards/art/paddlingout.webp?v=d429d6e4f8",
  "stories": "/assets/cards/art/stories.webp?v=189709c945"
});

/** The art for a card on the web: the WebP, or the PNG for a slug with none. */
export const artUrl = (c) => URLS[c.art || c.slug] || `/assets/cards/art/${c.art || c.slug}.png`;
